package com.gdgku.study.backend;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;


@RestController
public class MemoController {
    Map<String, Object> memos_list = new HashMap<>(Map.ofEntries(Map.entry("Drip과 매력", "- Drip은 자연스럽게 떨어지지만 그 과정에는오랜 시간이 쌓여있음"), Map.entry("가식과 의도", "- 가식은 의도적으로 노력한 행동,즉 의도적인 행동이다. 그렇다면 가식적인 행동이야말로 그 사람의 진짜 본성을 드러내는것이 아닌가? 그 사람이 어떤 의도로 행동하는지는 진솔한 행동보다 가식에서 보다 진솔하게 드러난다."), Map.entry("경험 수집가의 여행법", "- \"집에서 나를 그리워하는 사람이 있는 한, 멀고 험난한 장소를 얼마든지 즐길 수 있다.\"\n- \"나에 대해 개략적인 선입견만을 품은 사람들의 눈에 둘러싸일 때, 우린 꼭 위장한 것만 같고 익명이 된 것만 같다\"^17730b\n- 소련의 <종이건축가>\n\t- 당국의 허가 없어서 시공할 수 없는 건물들을 그저계속해서 설계한 사람들\n\t- 오히려 현실에 얽메이지 않는 아이디어가 나옴"), Map.entry("경험의 창발성", "- 여행, 술자리, 대학생활까지 많은 사람들이 \"제대로 즐기지 못했다\"고 말함\n- 그런데 여기서 놀이와 친목을 \"체험\"해보지 못한 사람은 흔치 않음. 그저\"충분히\" 경험하지 못했다고 생각할 뿐\n- 그렇다면 여기서 체험과 경험 사이의 창발적인 성질이 존재하는가?"), Map.entry("구걸에 대한 관점", "- 비루한 거지근성만 같아서넌더리가 났었는데 그게 아니라 있는 자에 대한 없는 자의 당당한 요구였다면 어쩔 것인가?"), Map.entry("기준과 심판", "- 8분경\n- 우리는 우리의 기준에 자신과 타인을 맞추며심판을 창조해냄\n- but 기준의 필요성은 없을까?\n- 나 혹은 타인에게 피해를 주는 것도관용해야하나? ex) 김민찬\n\t- 어쩌면 지향점으로서의 기준은 무의미하더라도 잘못된 것의 정의는 필요할지도?\n\t- 부정적 기준점의 필요성"), Map.entry("다양한 분야의 통일된 관점", "- 다양한 분야를 하나로 엮어 성과를 내려면 하나의 깊은 관점이 필요함\n- 자신이 진정으로 전문성을 가지는 하나의 분야가 그 관점으로서 기능할 수 있음\n- [[얕은 지식이 쉬워진 세상]]에서 더욱 중요"), Map.entry("두려움과 사랑", "- 두려움보단 사랑을쫓아 살아가야 한다\n- 두려움은 생존을 위한 감정이다. 두려움이 제시하는 방향을 따라가는 삶의 목표는 \"생존\"이 되고, 이는 필연적으로 찾아올 죽음을 피하고자 하는 싸움이된다. 패배가 정해진 싸움을 하며 살아가게 되는 것이다.\n- 그렇기에 우리는 이룰 수 있는 목표를 향하는 사랑으로 살아가야 한다."), Map.entry("맨 앤 스타일", "- \"멋지게 살아온 삶의 흔적을 포용하는 사람들은 매력적이다\"\n- 자신의 취향에 이유를 댈 수 있는사람이 되고싶다."), Map.entry("명료와 존재", "- \"막연하다고 해서 존재하지 않는 것은 아니다. 좋은 삶, 좋은 부모, 좋은 공동체처럼 말이다.\""), Map.entry("명상록", "- 사람은 자기가 소유하고 있지 않은 것은 빼앗길 수 없고, 모든 사람은 다 똑같이 현재라는순간만을 소유하고 있어서, 그가 누구든 오직 현재라는 순간만을 잃을 뿐이기 때문이다 -> 죽음의 평등성\n- 누군가로부터 갑자기 \"지금 무슨 생각을 하느냐\"는 질문을 받아도 그 즉시 아주 정직하게 답할 수 있는 그런 생각들을 하도록 스스로 훈련하여야 한다\n- 나자신에게 하는 조언의 형태를 띈 명상록\n- 너의 생각 속에 있는 모든 대상을 하나하나 모두 정확히 정의하고 서술해서 모든 부수적인 곁가지들을 다 제거했을 때 그 대상의 본질이 무엇인지를 알아야 하고 그 대상을 전체적으로 및 부분적으로 구별할 수 있어야 한다.\n- 찬사는 아름다움의 일부가 아니다. 찬사를 받는다고 해서 더 선해지지도 않고 더 악해지지도 않기 때문이다.\n\t- [[평판에 관하여]]\n- 기억하는 모든 것이 덧없고 기억되는 모든 것이 덧없다"), Map.entry("몽테뉴 수상록", "- 다른사람의 기준으로 나를 돌아보는 것이 아니라 스스로의 기준으로 판단하기 위해 나만의 법규와 법원을 두고 그곳에 나 자신을 제소한다\n\t- [[기조]]\n- 나는 타인의 논리에 수긍할 때 그 사실보다 그에 대한 내 무지에 대해 배운다. 우둔함에 대한 인식이 전체적인 개선으로 이어진다\n- 플라톤과 내가동일하게 보고 이해했다면 그것은 플라톤의 진리와 이성임과 동시에 나의 진리와 이성이기도 하다\n\t- 진리와 이성은 소유되지 않는다.\n- 평화로운 시절에든 전쟁중에든, 나는 절대 책 없이 여행을 떠나지 않는다. 그러나 그 책을 읽지 않은 채로 몇날 혹은 몇달을 지낼 수는 있다. (...) 책이 내 곁에 있어 내가 원할 때 즐거움을 줄 것이라는 상상만으로 내가 얼마나 평온해지는지 또 위안을 받는지 말로 표현할 길이 없을 정도다."), Map.entry("문학의 쓸모", "- 생산성이 향상되지 않는 분야들\n\t- 기초교육\n\t- 독서\n\t- 미용\n\t- 문학 등\n- 사회적 지위 향상과 야망\n\t- 사회적 지위 향상을 위해서는 야망이 있어야한다\n\t- 자식을 위한 부모의 야망.. 제자를 위한 스승의 야망 등\n- 자신을 타자화해서바라볼 수 있게 해주는 문학"), Map.entry("문화의 형성", "문화는 축적되는 것이다. 과거의 문화를 지우고 재창조할 수 없다\n[[경험 수집가의 여행법]]"), Map.entry("미니멀리즘", "- 미니멀리즘은 단순히 적은 물건을 가지고 있는 것이 아니라 이유없이 \"그냥\" 가지고 있는 물건이 없는 것이다"), Map.entry("분별과 질투", "- 경계를 긋고 우열을 분별하면 내가 가지지 못한 것이 좋아보임\n- 13분경\n- 부재에서 나오는 불편은 극명하나 소유에서 나오는 편익은 빠르게 적응되어 흐려짐"), Map.entry("불안을 극복하고 연애를 해야할까", "> 너도 문제투성이 같은데, 나랑 만나면 재밌어질것 같은데\n- 거침이 젊음의 특징이라면 왜 억지로 불안을 잠재워야 할까? 무미건조해진 노년이 오기 전 불안과 고뇌를충만히 경험하는게 합당하지 않을까?"), Map.entry("사랑을 배우는 방법", "- 사랑을 다룬 책에서 사랑을 배울 수 있을까? 다양한 사랑을 직간접적으로 경험하며 배우는 것이 아닐까?"), Map.entry("생각의 역할", "- 생각의 두가지 역할: 행동의 전과 후\n\t- 사전적 생각: 행동을 유발하는 동기\n\t- 사후적 생각: 행동과 현상을 해명하는 것"), Map.entry("소중한 것", "- 내가 가진 것 중에서 가장 소중한 것은 무엇일까\n- 아무래도 목숨이긴 하겠지..."), Map.entry("숟가락이 둥근 이유", "- 숟가락 둥근 이유\n\t- 뾰족하면 각진 곳 위에 고인 액체가 더 깊어 마찰력 비균등 -> 유체가 불안정하게 흐름\n\t- 둥글면 중심으로부터 마찰면의 거리가 상대적으로 균등함\n- 우리가 각지지 않게 살아야 하는 이유도 같음\n\t- 두뇌 속 수많은 분야의 생각들이 함꼐 부드럽게 흐르게 만들기 위함\n\t- 두뇌의표면과 여러 지식 사이 균등한 간격"), Map.entry("습관화된 가식과 본질", "- 우리의 본모습은 결국 습관의 총체이다. 그렇다면 습관화된 의식적 행동, 즉 가식은 본모습에 속할수 있는 것이 아닐까?\n- [[가식과 의도]]"), Map.entry("시와 펜의 춤", "- 함축적인 의미를 담고 있기에 내 해석과 생각을 펼칠 여백이 많은 시 -> 읽으면 더 많은 생각을 해볼수 있을듯"), Map.entry("여행과 관광", "[[경험 수집가의 여행법]]\n- 관광: 수동적, 장소를 바라봄\n- 여행: 능동적, 장소와 문화를 체험"), Map.entry("여행의 금기", "- \"꼭해야 하는\" 것은 여행에서 존재해선 안된다.\n- 의무는 경험의 재미를 상당부분 거세한다. 강요된 경험은 그 기반이 되는 \"이유\"에서 공백이 발생하며, 온전한 \"이야기\"로 자리잡기 어렵다."), Map.entry("영상과 의미", "- 보존에 비용이 들기에 보존된 영상은 남아있다는 사실 자체로 의미가 증명된다 [[영상커뮤니케이션과 기호학]]\n- but 기술발전으로 보존에 필요한 비용이 감소하며 의미 또한 옅어질지도?"), Map.entry("영상커뮤니케이션과 기호학", "- 영상과 실제의 관계\n\t- 영상회의론: 플라톤, 영상은 실제 담지 못함,개신교\n\t- 영상긍정론: 아리스토텔레스, 영상은 우리가 실제에 대해 정보 얻을 수단, 가톨릭\n- 기호란?\n\t- 소쉬르: 의미(기의)와 표현(기표)의 합\n\t- 퍼스: 표상체(표현)+대상체(표상체가 지시하는 대상, 의미)+해석체(표상과 대상을 연결하는 생각, 감정, 경험 등)\n- 영상의 보존과 제작에는 노력이 들어가기에 영상이 남아있다는 사실만으로 의도가 존재함을 보장한다."), Map.entry("예술에 대한 관심의 촉발", "- 내가 예술 작품에 관심을갖는 경우는 그것이 **열정과 괸계가 있을 때 뿐이었다.**\n- 예술사와 의도에 관한 거시적 예술 관람이 느낌과 개인적 맥락에 따른 미시적 예술 관람보다 꼭 우월할까? 설명을 읽어야 이해되는 예술의 해석이 우리에게 필요한가?\n- 나의 감상은 그 자체로 하나의 정답"), Map.entry("옳음과 좋음", "- 내게 옳은 것\n\t- 남에게 피해주지 않는 선에서 내 가능성을 최대한 펼치는 것\n\t- 세상에 새로움을 더하는 것\n\t- 더 많은 사람의 필요를 충족해주는 것\n- 내게 좋은 것\n\t- 내가 할 수 있는 것만 생각하는 것\n\t- 삶에서 배우는것\n\t- 헛되이 증오하지 않는 것"), Map.entry("요즘 예술은 정말 모르겠더라", "- 모더니즘의 방향: 장르의 순수성\n\t- 소설은 소설답게.. 회화는 회화답게\n\t- <--> 이전의사조\n\t\t- 회화가 2차원의 캔버스 위에 입체적 공간 재현 -> 시각적으로 공간의 환영이보임\n\t- -> 모더니즘에서는 환영을 제거하고 평면성을 추구함\n- 예술이 사물화된 이유\n\t- 회화는 캔버스와 물감이 다른 \"무언가\"로 인식됨(Ex. 2차원 그림이 3차원 공간으로 인식) -> 필연적인 \"환영\"발생\n\t- but 순수함을 위해서는 질료가 질료 그 자체로 인식되어야 함\n\t- 따라서 다른 것이 아닌 그 사물 자체로 인식될 수 있는 사물로서의 예술이 사조로 자리잡음\n- 프리드의 미니멀리즘 비판\n\t- 관객의 지각과 참여 중시하는 미니멀리즘 예술\n\t- but 지속적으로 관찰되는 미니멀리즘의 시간성은 회화보단 연극에 가까운 성질 -> 모더니즘적 순수성을 잃음\n- 개념미술\n\t- 예술의 본질을 관점, 질문과 같은 \"아이디어\", 즉 \"개념\"에 있다고 봄\n- 퍼포먼스\n\t- 미니멀리즘과의 대조\n\t\t-예술의 순수성과 탈개성화를 추구한 미니멀리즘 <-> 예술가를 전면에 내세우는 퍼포먼스예술\n\t\t- [[퍼포먼스 예술의 의미]]\n- 장소 특정적 미술\n\t- 예술과 사회를 분리하는 \"미술관\", \"화이트큐브\"라는 장소를 거부하고 특정 장소와 미술을 결합시킴\n- 예술사조의 흐름\n\t- 보이는 것 재현(고전) - 보이지 않는 것을 구현(현대) - 보여주지 않는것을 폭로(탈은폐)\n- 혼합현실: 현실의 영향을 받음으로서 단순히 현실과 다른 층위에서존재하는 증강현실과 차별되는 현실 속으로 혼합된 가상적 요소들\n- 인류세: 지질학적으로 인류가 의미를 가짐 -> 인류가 환경을 바꿀 힘을 가짐\n\t- [[인류세는 꼭 부정적인가]]"), Map.entry("욕망이라는 자산", "- 쾌락의 행위와 몸짓이 더해지는 만큼 우리는 확실히 조금씩 멀어져 가고 있었다. **우리는 욕망이라는 자산을 서서히 탕진하고 있었다.**\n- 탐색될수록 소진되는 자산으로서의 욕망"), Map.entry("웨스 앤더슨", "- 여느 위대한모험담에 등장하는 인물들이 그러하듯이, 밧줄을 타고 지상으로 내려갈 수 있다면 절대 정문으로 나가지 않는다.\n- 철저한 인위성 속 자연스러운 감정을 그린 웨스 앤더슨"), Map.entry("응원가 석탑이 좋은 이유", "- 하늘을 향해 우뚝 솟아오른 거대한 돌더미\n- [[중심잡힌 삶]] 연상"), Map.entry("이토록 굉장한 세계", "- 감지하는 원리와 반응을 알기는 쉬워도 그게 내면에 불러일으키는 주관적 느낌을 알기는 어렵다\n-"), Map.entry("인식되는 시간과 죽음", "- 객관적 시간보다 중요한건 인식되는 시간이다\n- 즉 죽음 이후의 인식되지 않는 시간은 의미가 없다"), Map.entry("인식이라는 허상", "- 우리가 인지하는 \"현실\"은 객관적 현실이 아니라 뇌가 만들어낸 주관적 해석이자 재현이다."), Map.entry("장식으로서의 커피", "- 들고있는 커피는 외관의 일부가 된다. 따라서 커피또한 나의 자기표현의 일부가 되었으면, \"멋지게 보였으면\"한다."), Map.entry("전기와 치팅시트", "-자기계발서가 공식이라면 전기는 누군가가 삶을 풀어나가는 과정이 담긴 \"풀이과정\"이다\n- 공식보다 풀이과정이 치팅시트로서 도움이 되었듯 전기도 도움이 될듯\n# \"어떻게 하는지\"는 배울 수 없습니다.\n## 강연이야기\n 최근 학교에서 다양한 강연을 듣고 있다.이전에는 강연을 듣는 것에 대해 잘 이해하지 못했다. 학교 수업과 무슨 차이인지도 잘 몰랐으며 다 뻔한 얘기처럼만 들렸기 때문이다. 하지만 \"알고 싶은 것\"이 생기니 강연은내게 많은 것을 가르쳐 주기 시작했다.\n 그렇게 다양한 강연을 듣다보니, 어떤 강연에서더 많은 것을 배웠는지에 대해 고민하게 되었다. 강연을 해주신 연사님들은 모두 훌륭한분들이셨다. 적어도 자신의 분야에서 성공을 거둔, \"어떻게 해야 하는가\"를 아시는 분들이셨다. 그럼에도 불구하고 어떤 강연은 내게 더 많은 것들을 가르쳐주었다. 그렇다면 무엇이 내가 배운 점의 차이를 만들었을까?\n## 전문가는 잘 가르칠까?\n보통 강연을 하는사람들은 \"전문가\"다. 어찌보면 당연하다. 누가 멋모르는 사람에게 강연을 듣고 싶겠는가? 우리는 한 분야의 전문가에게 방법을 배우기 위해 강연을 듣는다. \n 그러나 전문가는 자신이 하는 모든 일을 의식하지 않는다. 어쩌면 그 의식의 부재가 전문가의 조건일지도모른다. 숙련된다는 것은 어떤 일을 지적으로 자동화하는 것이기 때문이다.\n 우리가 처음 걸음마를 할 때, 우리는 우리가 내딛는 한걸음 한걸음을 모두 의식했을 것이다. 그러나지금, 우리는 우리가 \"어떻게\" 걷는지 의식하는가? 숨을 쉬고, 걷고, 밥을 먹는 모든 행위를 의식한다면 우리는 그 무엇도 할 수 없을 것이다. 그렇기에 우리는 누구에게도 \"걷는\" 법을 설명할 수 없다. 우리는 걷기의 방법에 대해 생각하지 않기 때문이다.\n 이는이러한 단순한 행동에만 국한되지 않는다. 한 연구에 따르면 외과의사가 수술 방법에 대한 수업에서 언급하는 내용은 실제 수술에 필요한 지식에 30%에 불과했다고 한다. 어떤 일을 하는 핵심적인 방법들은 전문가에게 너무도 당연한 것이다. 그렇기에 그 생략으로 인한공백이 우리의 배움을 방해한다. 그것이 어떤 전문가들의 설명에서는 배울 것이 적은 이유이다.\n## 어떻게 \"하는가\"와 어떻게 \"했는가\"\n어떻게 \"하는가\"에 대해 말할 때,우리는 많은 것들을 생략한다. 우리에게 체화된 것들, 우리가 당연하게 여기는 것들, 무의식적으로 이뤄지는 것들을 우리는 말하지 않는다. \n그렇다면 어떻게 우리는 필요한 내용을 빠짐없이 설명할 수 있을까? 어떤 강연에서 우리는 필요한 내용을 빠짐없이 배울 수 있을까?\n답은 \"이야기\"에 있다.\n어떻게 \"하는가\"는 일종의 이론이다. 방법의 나열이고 일반적인 원리다. 반면, 어떻게 \"헀는가\"는 하나의 이야기다. 어떤 일을 해나간 우리의 서사인 것이다.\n그럼 왜 이야기에서 우리는 더 많은 것을 배울 수 있을까? 그 이유는 몇가지가 있다.\n우선, 이야기는 현재가 아닌 과거의 시점을 다룬다. 아직 자동화되지 않았을 때, 방법들이 충분히 체화되지 않았을 때, 아직 모든 단계를 의식하고 있던 시절을 다룬다. 그렇기에 이야기 속, 그 당시에 했던 생각들을 말할 떄에는 생략이 덜하다.\n또 한가지는 우리의 뇌가, 이야기를 \"완성하고자\" 하기 때문이다. 우리는 이야기의 공백을 참지 못한다. 열린 결말과 소위 \"떡밥\"이 그렇게 매력적인 이유도 우리의 뇌가 그것을 완성하기 위해 다양한 이야기들을 내놓기 때문일 것이다. 이는 두가지 방면에서 우리에게 도움을 준다. 설명\"하는\" 입장에서는 공백을 최소화하며 이야기 하게 되고, 듣는 입장에서는 생략된 것을 쉽게 알아차릴 수 있다.\n이러한 이유로, 우리는 어떻게 \"하는가\"라는일반론보다 어떻게 \"했는가\"라는 사례에서 더 많은 것을 배울 수 있다. \n그런데 우리가 뭘 가르치거나, 강연을 듣는 경험이 그리 흔한 것은 아니다. 그렇다면 우리는 이 \"어떻게\"를 어떻게 써먹을 수 있을까?\n## 어떻게 \"했는가\"가 담긴 책, 문학과 전기\n나는이것을 \"어떤 책을 읽을 것인가\"라는 질문에 적용해보았다.\n많은 사람들은 자기계발,경제경영과 같이 \"이론\"이 담긴 비문학 책에서 더 많은 것을 배울 수 있다고 생각한다.물론 나 또한 그러한 책들에서 많은 것을 배웠고, 그 책들의 필요성, 특히 잘 쓴 비문학책에서는 정말 많은 것을 빠르게 배울 수 있다는 점에는 전적으로 동의한다.\n하지만 어쩌면 우리는 그 \"원리\"보다 누군가의 풀이과정에서 더 많은 것을 배울 수 있을지 모른다.그리고 그 어떻게 \"했는가\"를 담은 책이 바로 문학과 전기일 수 있다.\n문학과 전기는한 인물, 혹은 여러 인물의 삶을 다룬다. 그 이야기를 완성하기 위해 작가는 더 많은 사실을 서술한다. 그렇기에 앞서 말했던 것처럼 우리는 덜 생략된 지식을 배울 수 있는 것이다. 그러한 책들에서 우리는 \"진짜 방법\"을 배울 수 있는 것이다.\n한번쯤은, 정말 닮고싶은 사람, 정말 되고싶은 사람, 정말 이루고싶은 것을 이룬 사람을 찾아보자. 현실 속에서든, 소설 속에서든. 그리고 그 사람의 풀이과정을 훔쳐보며 무엇을 배울 수 있는지 생각해보자. 어쩌면 그것이 우리가 그토록 찾던 \"방법\"을 알려줄지도 모르니."), Map.entry("전문분야와 관심분야의 교집합", "- 전문분야와 관심분야의 교집합에 있는 일을 할때 과정도 결과도 행복할 수 있음\n- 전문분야가 [[다양한 분야의 통일된 관점]]으로서 작용함"), Map.entry("전해듣는 뇌", "- [[인식이라는 허상]]\n- 감각기관에게 그저 현실을 \"전해듣고\" 재현하는 우리의 인식"), Map.entry("좋겠습니다", "- \"좋겠습니다\"라는 말의 여러 의미\n\t- 부러움\n\t- 나를 상대에게 기쁨을 줄 수 있는 존재로 만듬\n\t- 나의 행동을 상대의 기분을 위해 제약하려함\n- 양면성\n\t- 나의 기쁨, 나의 성장에서 \"좋음\"이라는 감정을 느끼는 사람의 따듯함\n\t\t- \"네가 행복했으면 좋겠어\"\n\t- 나의 행동을자신의 기쁨을 위한 수단으로 삼는 상대에 대한 거부감\n\t\t- 네가 이렇게 해주면 좋겠다."), Map.entry("중요한 문제가 뭘까", "> 어떤 문제가 다른 문제보다 절박하다고 하는 판단 기준은 그 질문에 따라 마땅히 실천하게 되는 행동이다.\n- 질문의 중요성은 그에 따라오는 행동에서 기인한다"), Map.entry("퍼포먼스 예술의 의미", "- 극단적인 퍼포먼스의예술적 가치에 쉽사리 공감하긴 어려움\n- 그러나 의미를 찾는다면 행위자가 강조되는 행위의 성질에서 그 의미를 찾을 수 있을듯\n- 작가를 지우던 미니멀리즘 사조와 달리 퍼포먼스의 행위는 작가의 개인성이 맥락으로 작용해야 비로소 참된 의미 지님\n- 마리아의 경우도 개인의 서사가 작품의 의미를 형성함\n- 행위 자체가 행위자까지 의미의 맥락으로 끌어들여 의미를 구성한다는 성질이 있음\n- 퇴색되던 작가성을 부활시키려는 투쟁으로서의퍼포먼스"), Map.entry("편견과 익명성", "[[경험 수집가의 여행법#^17730b]]\n- 편견을통해 바라보는 대상은 마치 김서린 유리창을 통해 보는 것처럼 흐려진다. 개인으로서의 특징은 사라지고 편견에 포함된 개략적 형태만이 파악된다.\n- 따라서 때로 편견은 오히려우리에게 [[익명성]]을 부여한다."), Map.entry("하기 쉽지만 잘하기 어려운것", "- 노래.. 타격기 등 모두가 할 수 있지만 잘하기는 힘든 것들이 좋다"), Map.entry("학문의 경계를 만드는 것", "- 무엇을 **변수**로 둘 것인가\n\t- 주류경제학:제도가 상수\n\t- 제도경제학:제도도 변수"), Map.entry("행운의 본질", "- 예측불가능하다는 점에서, 행운은 본질적으로 불행과 같다"), Map.entry("헤세가 사랑한 순간들", "- 여행 가방과 취향\n\t-여행 가방을 쌀 때, 실용성은 큰 의미가 없다. 실용적인 것들은 어디서나 살 수 있고 어디에서 사도 큰 차이가 없기 때문이다. 중요한 것은 \"취향\"에 관한 물건들이다."), Map.entry("현재 상태와 무관하게 배울 점이 있는 이유", "- 지금 0에 있는 사람이 -10에서 올라왔다면 그는 적어도 10만큼 향상시키는 법을 가르쳐줄 수 있다.\n- 이중차분법의 analogy"), Map.entry("흐트러짐과 매력", "- 나는 흐트러짐이 예외적일때 그것이 매력으로 비치는 것 같다. 중심 자체가 흐트러진 사람이 아니라 [[중심잡힌 삶]] 속에서 약간의 흔들림을허용하는, 그런 삶을 원한다.")));

    public record MemoRequest(String title, String body) {
    }

    public record MemoResponse(String title, String body) {
    }

    @GetMapping("/memos")
    public ResponseEntity<MemoResponse> readMemo(){
        int index = ThreadLocalRandom.current().nextInt(memos_list.size());
        return memos_list.entrySet().stream()
            .skip(index)
            .findFirst()
            .map(entry -> ResponseEntity.ok(
                new MemoResponse(entry.getKey(), String.valueOf(entry.getValue()))))
            .orElseGet(() -> ResponseEntity.notFound().build());
    }

    @PostMapping("/memos")
    public ResponseEntity<MemoRequest> createMemo(@RequestBody MemoRequest entity) {
        memos_list.put(entity.title, entity.body);
        return ResponseEntity.status(HttpStatus.CREATED).body(entity);
    }
}
